            {self.dien_tich():.2f}, CV: {self.chu_vi():.2f}"
class HinhTron(Hinh):
    def __init__(self, ban_kinh):
        self.ban_kinh = ban_kinh

    def dien_tich(self):
        return math.pi * self.ban_kinh ** 2

    def chu_vi(self):
        return 2 * math.pi * self.ban_kinh

class HinhChuNhat(Hinh):
